    39  #define PACKET_HEADER_CHECK(_msg) do { \
    40          if (p > end) { \
    41                  fr_strerror_printf("Header for %s is too small (%zu < %zu)", _msg, end - (uint8_t const *) pkt, p - (uint8_t const *) pkt); \
    42                  goto fail; \
    43          } \
    44  } while (0)
    45
    46  #define ARG_COUNT_CHECK(_msg, _arg_cnt) do { \
    47          if ((p + _arg_cnt) > end) { \
    48                  fr_strerror_printf("Argument count %u overflows the remaining data in the packet", _arg_cnt); \
    49                  goto fail; \
    50          } \
    51          p += _arg_cnt; \
    52  } while (0)
    53
    54  #define DECODE_FIELD_UINT8(_da, _field) do { \
    55          vp = fr_pair_afrom_da(ctx, _da); \
    56          if (!vp) goto fail; \
    57          vp->vp_uint8 = _field; \
    58          fr_dcursor_append(cursor, vp); \
    59  } while (0)
    60
    61  #define DECODE_FIELD_STRING8(_da, _field) do { \
    62          if (tacacs_decode_field(ctx, cursor, _da, &p, \
    63              _field, end) < 0) goto fail; \
    64  } while (0)
    65
    66  #define DECODE_FIELD_STRING16(_da, _field) do { \
    67          if (tacacs_decode_field(ctx, cursor, _da, &p, \
    68              ntohs(_field), end) < 0) goto fail; \
    69  } while (0)
    70
    71  #define BODY(_x) (((uint8_t const *) pkt) + sizeof(pkt->hdr) + sizeof(pkt->_x))
